def accepted_details(protocol, receipts):
    # The accepted command returns the count/summary counts plus the accepted
    # representatives themselves, unchanged and in original input order.
    accepted = accepted_receipts(protocol, receipts)
    response = counts_for(protocol, receipts, accepted)
    response["receipts"] = accepted
    return response

